// HasChainOfCustody applies the HasEdge predicate on the "chain_of_custody" edge.
func HasChainOfCustody() predicate.Shipment {
	return predicate.Shipment(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, ChainOfCustodyTable, ChainOfCustodyColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasChainOfCustodyWith applies the HasEdge predicate on the "chain_of_custody" edge with a given conditions (other predicates).
func HasChainOfCustodyWith(preds ...predicate.ChainOfCustody) predicate.Shipment {
	return predicate.Shipment(func(s *sql.Selector) {
		step := newChainOfCustodyStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Shipment) predicate.Shipment {
	return predicate.Shipment(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Shipment) predicate.Shipment {
	return predicate.Shipment(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Shipment) predicate.Shipment {
	return predicate.Shipment(sql.NotPredicates(p))
}
